          "text": "const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d');ctx.strokeStyle='#3a866d';ctx.lineWidth=4;ctx.lineCap='round';let drawing=false;function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];}canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));};canvas.onpointermove=e=>{if(drawing){ctx.lineTo(...point(e));ctx.stroke();}};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;document.querySelector('button').onclick=()=>ctx.clearRect(0,0,canvas.width,canvas.height);\n"
